"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7540],{16355:e=>{e.exports=JSON.parse('{"functions":[{"name":"getThrowOriginDir","desc":"Throw origin + unit direction, shared by the preview and the real throw so both agree.\\nOrigin is the held item (Handle); while paused (throw animation) it is the last\\nhold-pose Handle spot, carried with the HumanoidRootPart so it follows the player.\\nDirection is the screen-center camera ray plus the lob bias (character facing when\\nthere is no camera yet).","params":[{"name":"character","desc":"","lua_type":"Model"},{"name":"tool","desc":"","lua_type":"Tool"}],"returns":[{"desc":"","lua_type":"Vector3"},{"desc":"","lua_type":"Vector3"}],"function_type":"static","source":{"line":156,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}},{"name":"show","desc":"Start showing the arc for an equipped throwable. Idempotent: a second call\\ntears the previous session down first. Captures `character`/`tool` for the\\nper-frame origin + raycast filtering.","params":[{"name":"config","desc":"","lua_type":"WeaponTypes.ThrowableWeaponConfig"},{"name":"character","desc":"","lua_type":"Model"},{"name":"tool","desc":"","lua_type":"Tool"}],"returns":[],"function_type":"static","source":{"line":261,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}},{"name":"setPaused","desc":"Pause (hide) or resume the line. ThrowableHandler pauses it while the throw\\nanimation plays; while paused the throw origin stays at the hold-pose spot.","params":[{"name":"on","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":303,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}},{"name":"hide","desc":"Stop showing the arc and destroy the whole pool. Safe to call when nothing\\nis showing.","params":[],"returns":[],"function_type":"static","source":{"line":315,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}}],"properties":[],"types":[],"name":"TrajectoryPreview","desc":"Client-only predictive arc for thrown weapons (Grenade, Bomb). While a throwable\\nis equipped, `show` starts a RenderStepped loop that, each frame, starts the line\\nat the held item, steps the ballistic flight from `getThrowOriginDir`, raycasts\\neach step to stop at real geometry, and bounces off what it hits with the engine\'s\\nelasticity/friction mix (values from ThrowPhysicsConfig, the same ones\\nServerProjectile uses). The line ends at the second bounce, or at the first touch\\nwhen the charge does not hop, with a landing marker. ThrowableHandler throws from\\nthe SAME `getThrowOriginDir` and pauses the line while the throw animation plays.\\nPurely cosmetic and local \u2014 no networking. `hide` tears the pool down via one Janitor.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}}')}}]);